//! Third-party license popup.

use crate::prelude::*;

/// License texts of all dependencies, generated by `cargo about` (see licenses/README.md).
pub(crate) const THIRD_PARTY_LICENSES: &str = include_str!("../../licenses/THIRD_PARTY_LICENSES.txt");

pub(crate) static LICENSE_LINES: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();

impl Explorer {
    /// "licenses": the licenses of all bundled libraries in a scrollable popup.
    /// The text is generated by `cargo about and compiled into the exe.
    pub(crate) fn ui_licenses(&mut self, ui: &mut Ui) {
        if !self.licenses_open {
            return;
        }
        let (m, pal) = (self.m, self.pal);
        let height = (ui.content_rect().height() * 0.7).clamp(m.s * 200.0, m.s * 640.0);
        let closed = dialog_shell(
            ui,
            &m,
            &pal,
            "licenses",
            "Licenses",
            true,
            (ui.content_rect().width() * 0.9).clamp(m.s * 300.0, m.s * 760.0),
            |ui| {
                ui.label(
                    RichText::new(format!(
                        "FileFly v{} includes the following open-source software.",
                        env!("CARGO_PKG_VERSION")
                    ))
                    .color(pal.text_secondary),
                );
                ui.add_space(m.pad);
                egui::Frame::new()
                    .fill(fl_card_fill(&pal))
                    .stroke(Stroke::new(1.0_f32, pal.divider))
                    .corner_radius(CornerRadius::same(m.radius))
                    .inner_margin(Margin::same(m.pad as i8))
                    .show(ui, |ui| {
                        // Hundreds of crates make this text large: draw only the visible lines.
                        let lines = LICENSE_LINES.get_or_init(|| THIRD_PARTY_LICENSES.lines().collect());
                        let font = FontId::monospace(m.font * 0.85);
                        let row_h = ui
                            .painter()
                            .layout_no_wrap("A".to_owned(), font.clone(), pal.text)
                            .size()
                            .y;
                        ui.spacing_mut().item_spacing.y = 0.0;
                        egui::ScrollArea::both()
                            .id_salt("licenses_scroll")
                            .max_height(height)
                            .auto_shrink([false, false])
                            .show_rows(ui, row_h, lines.len(), |ui, range| {
                                for line in &lines[range] {
                                    ui.add(
                                        egui::Label::new(
                                            RichText::new(*line).font(font.clone()).color(pal.text),
                                        )
                                        .extend(),
                                    );
                                }
                            });
                    });
            },
        );
        if closed {
            self.licenses_open = false;
        }
    }
}
